    const n = parseInt(input[0]);
    const k = parseInt(input[1]);

    // Generate all valid permutations
    let permutations = [];
    generatePermutations(n, permutations);

    // Sort lexicographically
    permutations.sort((a, b) => {
        for (let i = 0; i < n; i++) {
            if (a[i] !== b[i]) return a[i] - b[i];
        }
        return 0;
    });

    // Output the k-th permutation (1-based index)
    console.log(permutations[k-1].join(' '));
}

function generatePermutations(n, result) {
    let perm = Array.from({length: n}, (_, i) => i + 1);
    do {
        if (isFixedPoint(perm)) {
            result.push([...perm]);
        }
    } while (nextPermutation(perm));
}

function isFixedPoint(perm) {
    let n = perm.length;
    let visited = Array(n).fill(false);
    let cycles = [];

    for (let i = 0; i < n; i++) {
        if (!visited[i]) {
            let cycle = [];
            let j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push(j + 1); // 1-based index
                j = perm[j] - 1; // perm[j] is 1-based value
            }
            cycles.push(cycle);
        }
    }

    // Standardize cycles: rotate to start with max element
    let standardized = cycles.map(cycle => {
        let maxIdx = cycle.indexOf(Math.max(...cycle));
        return [...cycle.slice(maxIdx), ...cycle.slice(0, maxIdx)];
    });

    // Sort cycles by their first element
    standardized.sort((a, b) => a[0] - b[0]);

    // Concatenate cycles
    let concatenated = standardized.flat();

    // Compare with original permutation
    for (let i = 0; i < n; i++) {
        if (concatenated[i] !== perm[i]) return false;
    }
    return true;
}

function nextPermutation(arr) {
    let n = arr.length;
    let i = n - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) i--;
    if (i < 0) return false;

    let j = n - 1;
    while (arr[j] <= arr[i]) j--;
    [arr[i], arr[j]] = [arr[j], arr[i]];

    let left = i + 1;
    let right = n - 1;
    while (left < right) {
        [arr[left], arr[right]] = [arr[right], arr[left]];
        left++;
        right--;
    }
    return true;
}

