function solve(n, k) {
    const permutations = generateFixedPermutations(n);
    permutations.sort((a, b) => lexCompare(a, b));
    return permutations[k - 1];
}

function generateFixedPermutations(n) {
    const result = [];
    const visited = Array(n + 1).fill(false);
    backtrack([], visited, n, result);
    return result;
}

function backtrack(current, visited, n, result) {
    if (current.length === n) {
        if (isFixed(current)) {
            result.push([...current]);
        }
        return;
    }
    for (let i = 1; i <= n; i++) {
        if (!visited[i]) {
            visited[i] = true;
            current.push(i);
            backtrack(current, visited, n, result);
            current.pop();
            visited[i] = false;
        }
    }
}

function isFixed(perm) {
    const cycles = getCycles(perm);
    const standard = getStandard(cycles);
    const flattened = standard.flat();
    for (let i = 0; i < perm.length; i++) {
        if (perm[i] !== flattened[i]) return false;
    }
    return true;
}

function getCycles(perm) {
    const n = perm.length;
    const visited = Array(n + 1).fill(false);
    const cycles = [];
    for (let i = 1; i <= n; i++) {
        if (!visited[i]) {
            const cycle = [];
            let current = i;
            while (!visited[current]) {
                visited[current] = true;
                cycle.push(current);
                current = perm[current - 1];
            }
            cycles.push(cycle);
        }
    }
    return cycles;
}

function getStandard(cycles) {
    const modified = cycles.map(cycle => {
        const max = Math.max(...cycle);
        const idx = cycle.indexOf(max);
        return [...cycle.slice(idx), ...cycle.slice(0, idx)];
    });
    modified.sort((a, b) => a[0] - b[0]);
    return modified;
}

function lexCompare(a, b) {
    for (let i = 0; i < a.length; i++) {
        if (a[i] < b[i]) return -1;
        if (a[i] > b[i]) return 1;
    }
    return 0;
}

