function main() {
    const readline = require('readline');
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    let input = '';
    rl.on('line', (line) => { input = line; });
    rl.on('close', () => {
        const [n, k] = input.trim().split(' ').map(Number);
        const result = findPermutation(n, k);
        console.log(result.join(' '));
    });
}

function findPermutation(n, k) {
    const perm = [];
    const used = new Array(n + 1).fill(false);
    generate(perm, used, n, k);
    return perm;
}

function generate(perm, used, n, k) {
    if (perm.length === n) {
        return;
    }
    for (let i = 1; i <= n; i++) {
        if (used[i]) continue;
        perm.push(i);
        used[i] = true;
        const count = countValid(perm, used, n);
        if (count >= k) {
            generate(perm, used, n, k);
            return;
        }
        k -= count;
        perm.pop();
        used[i] = false;
    }
}

function countValid(perm, used, n) {
    const m = perm.length;
    if (m === 0) return factorial(n);
    let total = 0;
    const fixed = new Array(n + 1).fill(false);
    for (let i = 0; i < m; i++) {
        fixed[perm[i]] = true;
    }
    const remaining = [];
    for (let i = 1; i <= n; i++) {
        if (!fixed[i]) remaining.push(i);
    }
    const r = remaining.length;
    if (r === 0) return 1;
    const cycles = [];
    const visited = new Array(r).fill(false);
    for (let i = 0; i < r; i++) {
        if (visited[i]) continue;
        let len = 0;
        let j = i;
        while (!visited[j]) {
            visited[j] = true;
            len++;
            const val = remaining[j];
            let nextIdx = -1;
            for (let k = 0; k < r; k++) {
                if (!visited[k] && remaining[k] === perm[val - 1]) {
                    nextIdx = k;
                    break;
                }
            }
            if (nextIdx !== -1) j = nextIdx;
        }
        cycles.push(len);
    }
    let denom = 1;
    for (const c of cycles) {
        denom *= c;
    }
    total = factorial(r) / denom;
    return total;
}

function factorial(x) {
    let res = 1;
    for (let i = 2; i <= x; i++) res *= i;
    return res;
}

