        const result = solve(n, k);
        console.log(result.join(' '));
    });
}

function solve(n, k) {
    const memo = new Map();

    function count(m) {
        if (m === 0) return 1n;
        if (m === 1) return 1n;
        const key = m;
        if (memo.has(key)) return memo.get(key);
        let res = 0n;
        for (let i = 1; i <= m; i++) {
            res += count(m - i);
        }
        memo.set(key, res);
        return res;
    }

    function build(m, target) {
        if (m === 0) return [];
        let remaining = target;
        for (let i = 1; i <= m; i++) {
            const cnt = count(m - i);
            if (remaining <= cnt) {
                const perm = build(m - i, remaining);
                perm.unshift(i);
                return perm;
            }
            remaining -= cnt;
        }
        return [];
    }

    const perm = build(n, BigInt(k));
    return perm;
}

