const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

function main() {
    rl.on('line', (line) => {
        const [n, k] = line.split(' ').map(Number);
        const result = solve(n, k);
        console.log(result.join(' '));
        rl.close();
    });
}

function solve(n, k) {
    const perm = Array.from({ length: n }, (_, i) => i + 1);
    let count = 0;
    do {
        if (isValid(perm)) {
            count++;
            if (count === k) return perm.slice();
        }
    } while (nextPermutation(perm) && count < k);
    return perm;
}

function isValid(perm) {
    const cycles = getStandardCycles(perm);
    const transformed = cycles.flat();
    return transformed.join('') === perm.join('');
}

function getStandardCycles(perm) {
    const visited = new Array(perm.length).fill(false);
    const cycles = [];
    for (let i = 0; i < perm.length; i++) {
        if (!visited[i]) {
            const cycle = [];
            let j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push(j + 1);
                j = perm[j] - 1;
            }
            const maxIdx = cycle.indexOf(Math.max(...cycle));
            const rotated = [...cycle.slice(maxIdx), ...cycle.slice(0, maxIdx)];
            cycles.push(rotated);
        }
    }
    cycles.sort((a, b) => a[0] - b[0]);
    return cycles;
}

function nextPermutation(arr) {
    let i = arr.length - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) i--;
    if (i < 0) return false;
    let j = arr.length - 1;
    while (arr[j] <= arr[i]) j--;
    [arr[i], arr[j]] = [arr[j], arr[i]];
    let left = i + 1, right = arr.length - 1;
    while (left < right) {
        [arr[left], arr[right]] = [arr[right], arr[left]];
        left++;
        right--;
    }
    return true;
}

