function solve(n, k) {
    const memo = {};
    function count(m) {
        if (m in memo) return memo[m];
        if (m === 0) return 1;
        let res = 0;
        for (let i = 1; i <= m; i++) {
            res += count(m - i) * comb(m - 1, i - 1);
        }
        return memo[m] = res;
    }

    function comb(n, k) {
        if (k < 0 || k > n) return 0;
        if (k === 0 || k === n) return 1;
        let res = 1;
        for (let i = 1; i <= k; i++) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }

    function generate(m, idx) {
        if (m === 0) return [];
        for (let i = 1; i <= m; i++) {
            const c = count(m - i) * comb(m - 1, i - 1);
            if (idx <= c) {
                const rest = generate(m - i, idx);
                const cycle = Array.from({ length: i }, (_, j) => j + 1);
                return [cycle, ...rest];
            }
            idx -= c;
        }
        return [];
    }

    const cycles = generate(n, k);
    const perm = Array(n).fill(0);
    for (const cycle of cycles) {
        const len = cycle.length;
        for (let i = 0; i < len; i++) {
            const pos = cycle[i] - 1;
            const next = cycle[(i + 1) % len];
            perm[pos] = next;
        }
    }
    return perm;
}

