function solve(n, k) {
    const memo = new Map();

    function countPermutations(n) {
        if (n === 0) return 1n;
        if (memo.has(n)) return memo.get(n);

        let total = 0n;
        for (let i = 1; i <= n; i++) {
            total += countPermutations(n - i);
        }
        memo.set(n, total);
        return total;
    }

    function generatePermutation(n, k) {
        if (n === 0) return [];

        let remainingK = BigInt(k) - 1n;
        const perm = [];
        const used = new Array(n + 1).fill(false);

        for (let pos = 0; pos < n; pos++) {
            for (let num = 1; num <= n; num++) {
                if (used[num]) continue;

                const cycleLength = num - perm.length;
                if (cycleLength < 1) continue;

                const remaining = n - perm.length - cycleLength;
                const count = countPermutations(remaining);

                if (remainingK < count) {
                    perm.push(num);
                    used[num] = true;
                    break;
                } else {
                    remainingK -= count;
                }
            }
        }

        return perm;
    }

    return generatePermutation(n, k);
}

