        const result = generatePermutation(n, k);
        console.log(result.join(' '));
        rl.close();
    });
}

function generatePermutation(n, k) {
    const permutation = Array.from({ length: n }, (_, i) => i + 1);
    let currentK = k - 1;
    const cycles = [];
    let remaining = n;
    let start = 0;

    while (remaining > 0) {
        const cycleLength = findCycleLength(remaining, currentK);
        const cycle = permutation.slice(start, start + cycleLength);
        cycles.push(cycle);
        currentK -= cycleLength > 1 ? factorial(cycleLength - 1) : 0;
        start += cycleLength;
        remaining -= cycleLength;
    }

    const result = Array(n).fill(0);
    for (const cycle of cycles) {
        const max = Math.max(...cycle);
        const maxIndex = cycle.indexOf(max);
        const rotated = [...cycle.slice(maxIndex), ...cycle.slice(0, maxIndex)];
        for (let i = 0; i < rotated.length; i++) {
            result[rotated[i] - 1] = rotated[(i + 1) % rotated.length];
        }
    }

    return result;
}

function findCycleLength(remaining, k) {
    let cycleLength = 1;
    let currentK = k;
    while (currentK >= factorial(cycleLength) && cycleLength < remaining) {
        currentK -= factorial(cycleLength);
        cycleLength++;
    }
    return cycleLength;
}

function factorial(n) {
    let result = 1;
    for (let i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

