}

function findPermutation(n, k) {
    const perm = [];
    const used = new Array(n + 1).fill(false);
    const cycles = [];
    let currentCycle = [];

    function backtrack(pos) {
        if (pos === n + 1) {
            if (currentCycle.length > 0) {
                cycles.push([...currentCycle]);
                currentCycle = [];
            }
            return;
        }

        for (let num = 1; num <= n; num++) {
            if (!used[num]) {
                used[num] = true;
                currentCycle.push(num);
                backtrack(pos + 1);
                currentCycle.pop();
                used[num] = false;
            }
        }
    }

    backtrack(1);

    const validPerms = [];
    for (const cycleSet of cycles) {
        const perm = new Array(n + 1).fill(0);
        for (const cycle of cycleSet) {
            for (let i = 0; i < cycle.length; i++) {
                perm[cycle[i]] = cycle[(i + 1) % cycle.length];
            }
        }
        validPerms.push(perm.slice(1));
    }

    validPerms.sort((a, b) => {
        for (let i = 0; i < n; i++) {
            if (a[i] !== b[i]) return a[i] - b[i];
        }
        return 0;
    });

    return validPerms[k - 1];
}

